func (f folderDo) FindInBatch(batchSize int, fc func(tx gen.Dao, batch int) error) (results []*store.Folder, err error) {
	buf := make([]*store.Folder, 0, batchSize)
	err = f.DO.FindInBatches(&buf, batchSize, func(tx gen.Dao, batch int) error {
		defer func() { results = append(results, buf...) }()
		return fc(tx, batch)
	})
	return results, err
}

